Method.Implementation:
    $$$TRACE("call web service " _ pRequest.ClinFileNm _", " _ pRequest.InXDRTouchWorksPnRFileNm)
    set pResponse = ##class(Ens.StringResponse).%New()
    set pResponse.StringValue = "Curl to send data to WebService"

    set curlOutFileNm = pRequest.workPath _ "newDataFile-" _ pRequest.clinID 
    set stat = ##class(IHC.ITF.ITFCOMMON.Utility).ExecuteShellCmd("/WORK/CLINDEV/bin/createCurl " _ pRequest.InXDRTouchWorksPnRFileNm _ " " _ pRequest.ClinFileNm _ " " _ pRequest.clinID _ " " _ curlOutFileNm, pRequest.workPath _ "curlFileOut-"_ pRequest.clinID, pRequest.workPath _ "curlFileErr-"_ pRequest.clinID)
    If ##class(%File).Exists(curlOutFileNm)
    {
	    $$$TRACE( "Script created: " _ curlOutFileNm)
        set stat = ##class(IHC.ITF.ITFCOMMON.Utility).ExecuteShellCmd("/WORK/CLINDEV/bin/EnsembleSend.cmd " _ curlOutFileNm, pRequest.workPath _ "curlOut-"_ pRequest.clinID, pRequest.workPath _"curlErr-"_ pRequest.clinID)
        $$$TRACE("ExecuteShellCmd: /WORK/CLINDEV/bin/EnsembleSend.cmd: " _ stat)
        if (stat = 0)
        {
        	set pResponse = ##class(Ens.StringResponse).%New()
        	set pResponse.StringValue = "Called Curl to send data to WebService"
        	set stat = $$$OK
        }
    }
    else
    {
	    set stat = $$$ERROR("Could not create curl file: " _ curlOutFileNm _", error: " _ stat)
    }

 QUIT stat
